from cardio_1 import a, G
# J82 — Éosinophilies pulmonaires (P-02-Pneumologie). Clés absentes de glossary/*.py et des glossaires des dossiers de travail au 09.10.2026.
a('PCE', [('P', 'Pneumopathie'), ('C', 'Chronique'), ('E', 'à Éosinophiles')], 'Pneumopathie chronique à éosinophiles', '<p>Pneumopathie d’évolution subaiguë ou chronique, avec éosinophilie sanguine ou alvéolaire et opacités pulmonaires à prédominance périphérique, retenue après exclusion des causes connues (maladie de Carrington). Elle répond rapidement aux glucocorticoïdes mais récidive souvent.</p>', 'j82-pce-def')
a('PAE', [('P', 'Pneumopathie'), ('A', 'Aiguë'), ('E', 'à Éosinophiles')], 'Pneumopathie aiguë à éosinophiles', '<p>Pneumopathie fébrile d’installation rapide, souvent hypoxémiante, avec éosinophilie au lavage broncho-alvéolaire alors que l’éosinophilie sanguine manque souvent au début. Elle survient volontiers chez un adulte jeune après le début ou la reprise du tabagisme et ne récidive pas.</p>', 'j82-pae-def')
a('GEPA', [('G', 'Granulomatose'), ('E', 'Éosinophilique'), ('P', 'avec Poly-'), ('A', 'Angéite')], 'Granulomatose éosinophilique avec polyangéite', '<p>Vascularite des petits vaisseaux associée aux ANCA, anciennement syndrome de Churg et Strauss : asthme, éosinophilie et atteinte granulomateuse ou vascularitique de plusieurs organes. Abréviation française employée par l’information professionnelle suisse ; équivalent anglais EGPA.</p>', 'j82-gepa')
a('SHE', [('S', 'Syndrome'), ('H', 'Hyper-'), ('E', 'Éosinophilique')], 'Syndrome hyperéosinophilique', '<p>Hyperéosinophilie sanguine d’au moins 1,5 G/L, constatée à deux reprises à au moins deux semaines d’intervalle, avec une atteinte d’organe attribuable aux éosinophiles, après exclusion des autres causes (Valent, 2023).</p>', 'j82-she')
a('HTLV-1', [('H', 'Human (humain)'), ('T', 'T-cell (à cellules T)'), ('L', 'Lymphotropic (lymphotrope)'), ('V', 'Virus'), ('1', 'de type 1')], 'Virus T-lymphotrope humain de type 1', '<p>Rétrovirus qui infecte les lymphocytes T. Chez un porteur de <i>Strongyloides stercoralis</i>, cette infection favorise l’hyperinfection, au même titre que les glucocorticoïdes et les autres immunosuppresseurs (Carnino, 2021).</p>', 'j82-strongy')
